// ---------------------------------------------------------------------------
// hex helpers
// ---------------------------------------------------------------------------

std::string image_word_hex(const std::bitset<256>& bits) {
    static const char* HEX = "0123456789abcdef";
    std::string out(64, '0');
    for (int i = 0; i < 64; ++i) {
        unsigned v = 0;
        for (int b = 0; b < 4; ++b)
            if (bits[static_cast<size_t>(4 * i + b)]) v |= 1u << b;
        out[static_cast<size_t>(63 - i)] = HEX[v];
    }
    return out;
}

std::bitset<256> image_word_from_hex(const std::string& text) {
    if (text.size() != 64) throw std::runtime_error("word length");
    std::bitset<256> out;
    for (int i = 0; i < 64; ++i) {
        char c = text[static_cast<size_t>(63 - i)];
        unsigned v;
        if (c >= '0' && c <= '9') v = static_cast<unsigned>(c - '0');
        else if (c >= 'a' && c <= 'f') v = static_cast<unsigned>(c - 'a' + 10);
        else throw std::runtime_error("word hex");
        for (int b = 0; b < 4; ++b)
            out[static_cast<size_t>(4 * i + b)] = ((v >> b) & 1u) != 0u;
    }
    return out;
}

// ---------------------------------------------------------------------------
// image validation
// ---------------------------------------------------------------------------

namespace {

struct ChildRef {
    uint8_t key = 0;
    int stage = 0;
    uint32_t cell = 0;
    bool bulk = false;
    int index = -1;
};

struct PNode {
    int stage = 0, origin = 0, level = 0, depth = 0, type = 0;
    uint32_t cell = 0, span = 0;
    ip6_t region{};
    uint32_t bmp = 0;
    uint16_t bitmap_id = 0;
    uint32_t ni_base = 0;
    uint64_t ni_bitmap = 0;
    uint32_t ni_count = 0;
    uint64_t bulk_bitmap = 0;
    uint32_t bulk_base = 0;
    int bulk_stage = 0;
    std::vector<PrefixRec> pfx;
    std::vector<ChildRef> children;
    uint64_t subtree = 0;
};

struct BitReader {
    const std::bitset<256>& bits;
    int pos;
    uint64_t r(int n) {
        uint64_t v = 0;
        for (int i = 0; i < n; ++i)
            if (bits[static_cast<size_t>(pos + i)]) v |= 1ULL << i;
        pos += n;
        return v;
    }
    bool zero(int from, int n) const {
        for (int i = 0; i < n; ++i)
            if (bits[static_cast<size_t>(from + i)]) return false;
        return true;
    }
};

int bit_length(uint32_t v) { return 32 - __builtin_clz(v); } // v >= 1

PrefixRec make_prefix(int origin, const ip6_t& region, int rel, uint64_t frag, uint32_t hop) {
    PrefixRec p;
    p.len = static_cast<uint8_t>(origin + rel);
    p.hop = hop;
    if (origin == 0) {
        p.addr.hi = frag;
        p.addr.lo = 0;
    } else if (origin == 16) {
        uint64_t v = (rel >= 64) ? frag : (frag >> (64 - rel));
        p.addr.hi = region.hi | (v << (48 - rel));
        p.addr.lo = 0;
    } else {
        p.addr.hi = region.hi;
        p.addr.lo = frag;
    }
    mask_prefix(p.addr, p.len);
    return p;
}

class Validator {
public:
    bool run(const ImageData& d);

private:
    const ImageData* d_ = nullptr;
    std::vector<std::vector<uint8_t> > covered_;
    std::vector<PNode> nodes_;
    std::map<std::pair<int, uint32_t>, size_t> index_;
    std::vector<PrefixRec> fib_;

    bool parse(int stage, uint32_t cell, bool bulk, int origin, int level, const ip6_t& region);
    bool finish();
    bool match(const GNode* g, size_t idx);
    bool read_child(uint64_t v, int stage, int origin, bool& bulk_out, ChildRef& out);
};

bool Validator::run(const ImageData& d) {
    d_ = &d;

    // bank sizes must match the charged cell counts exactly
    for (int s = 0; s < RAM_NUM; ++s) {
        size_t expect = (static_cast<size_t>(d.cells[static_cast<size_t>(s)]) + 1) / 2;
        if (d.banks[static_cast<size_t>(s)].size() != expect) return false;
    }
    // the bitmap dictionary is strictly increasing
    for (size_t i = 1; i < d.bitmaps.size(); ++i)
        if (d.bitmaps[i] <= d.bitmaps[i - 1]) return false;
    // fronts are sorted by numeric key and unique
    for (int f = 0; f < 2; ++f) {
        const std::vector<ImageFront>& v = (f == 0) ? d.front16 : d.front64;
        for (size_t i = 1; i < v.size(); ++i)
            if (v[i].key <= v[i - 1].key) return false;
    }
    // locators resolve
    if (d.root.stage >= 0) {
        if (d.root.stage >= RAM_NUM) return false;
        if (d.root.cell >= d.cells[static_cast<size_t>(d.root.stage)]) return false;
    }
    for (int f = 0; f < 2; ++f) {
        const std::vector<ImageFront>& v = (f == 0) ? d.front16 : d.front64;
        for (size_t i = 0; i < v.size(); ++i) {
            if (v[i].loc.stage >= RAM_NUM || v[i].loc.stage < 0) return false;
            if (v[i].loc.cell >= d.cells[static_cast<size_t>(v[i].loc.stage)]) return false;
        }
    }

    covered_.assign(static_cast<size_t>(RAM_NUM), std::vector<uint8_t>());
    for (int s = 0; s < RAM_NUM; ++s)
        covered_[static_cast<size_t>(s)].assign(d.cells[static_cast<size_t>(s)], 0);

    nodes_.clear();
    index_.clear();
    fib_.clear();

    if (d.root.stage >= 0) {
        ip6_t region;
        if (!parse(d.root.stage, d.root.cell, false, 0, 0, region)) return false;
    }
    for (size_t i = 0; i < d.front16.size(); ++i) {
        ip6_t region;
        region.hi = d.front16[i].key << 48;
        if (!parse(d.front16[i].loc.stage, d.front16[i].loc.cell, false, 16, 0, region))
            return false;
    }
    for (size_t i = 0; i < d.front64.size(); ++i) {
        ip6_t region;
        region.hi = d.front64[i].key;
        if (!parse(d.front64[i].loc.stage, d.front64[i].loc.cell, false, 64, 0, region))
            return false;
    }

    return finish();
}

bool Validator::parse(int stage, uint32_t cell, bool bulk, int origin, int level,
                      const ip6_t& region) {
    const int max_len = (origin == 0) ? 16 : (origin == 16 ? 64 : 128);
    const int depth = origin + 6 * level;
    if (depth > max_len) return false;
    if (stage < 0 || stage >= RAM_NUM) return false;
    if (cell >= d_->cells[static_cast<size_t>(stage)]) return false;

    const std::bitset<256>& bits =
        d_->banks[static_cast<size_t>(stage)][cell / 2];
    const int off = 128 * static_cast<int>(cell & 1u);
    BitReader rd{bits, off};

    const uint32_t type = static_cast<uint32_t>(rd.r(3));
    if (type < 1 || type > 5) return false;
    const uint32_t ordinary = (type == 1 || type == 4) ? 1u : 2u;
    const uint32_t span = bulk ? 2u : ordinary;
    if (span == 2u && (cell & 1u)) return false;       // full records: even cells
    if (static_cast<uint64_t>(cell) + span > d_->cells[static_cast<size_t>(stage)])
        return false;
    std::vector<uint8_t>& cov = covered_[static_cast<size_t>(stage)];
    for (uint32_t i = 0; i < span; ++i) {
        if (cov[cell + i]) return false;               // every node has one parent
        cov[cell + i] = 1;
    }
    if (span == 2u && ordinary == 1u) {                // zero padded upper half
        if (!rd.zero(128, 128)) return false;
    }

    PNode pn;
    pn.stage = stage;
    pn.cell = cell;
    pn.span = span;
    pn.origin = origin;
    pn.level = level;
    pn.depth = depth;
    pn.region = region;
    pn.type = static_cast<int>(type);
    pn.bmp = static_cast<uint32_t>(rd.r(22));
    pn.bulk_stage = -1;

    std::vector<ChildRef> refs;

    if (type == 4 || type == 5) {
        const int cnt = (type == 4) ? 1 : 2;
        for (int i = 0; i < cnt; ++i) {
            const uint64_t frag = rd.r(64);
            const int rel = static_cast<int>(rd.r(8));
            const uint32_t hop = static_cast<uint32_t>(rd.r(22));
            if (hop == HOP_NULL) return false;         // hop fields are never null
            if (origin == 0) { if (rel < 0 || rel > 16) return false; }
            else if (origin == 16) { if (rel < 1 || rel > 48) return false; }
            else { if (rel < 1 || rel > 64) return false; }
            if (origin + rel < depth) return false;    // global length >= node depth
            if (frag & low_mask(64 - rel)) return false; // host bits must be clear
            PrefixRec p = make_prefix(origin, region, rel, frag, hop);
            if (!prefix_of(region, depth, p.addr)) return false; // belongs to region
            pn.pfx.push_back(p);
        }
        if (type == 5 && !(pn.pfx[0].addr == pn.pfx[1].addr) == false) { /* checked below */ }
        if (type == 5 && pn.pfx[0].addr == pn.pfx[1].addr && pn.pfx[0].len == pn.pfx[1].len)
            return false;                              // distinct prefixes
        if (!rd.zero(rd.pos, (type == 4) ? 9 : 43)) return false;
    } else {
        pn.bitmap_id = static_cast<uint16_t>(rd.r(16));
        pn.ni_base = static_cast<uint32_t>(rd.r(22));
        if (pn.bitmap_id >= d_->bitmaps.size()) return false;
        const uint64_t bm = d_->bitmaps[pn.bitmap_id];
        if (bm & 1ULL) return false;                   // bit 0 is unused
        pn.ni_bitmap = bm;
        pn.ni_count = static_cast<uint32_t>(popcnt64(bm));
        if (pn.ni_count == 0) {
            if (pn.ni_base != 0) return false;         // empty arrays have base 0
        } else if (static_cast<uint64_t>(pn.ni_base) + pn.ni_count >
                   d_->nexthops.size()) {
            return false;
        }

        if (type == 1 || type == 2) {
            const int slots = (type == 1) ? 2 : 6;
            int present = 0;
            uint32_t prev_key = 0;
            bool absent_seen = false;
            for (int i = 0; i < slots; ++i) {
                const uint64_t v = rd.r(32);
                if (v == CHILD_ABSENT) { absent_seen = true; continue; }
                if (absent_seen) return false;         // absent records come last
                ChildRef c;
                if (!read_child(v, stage, origin, c.bulk, c)) return false;
                if (c.key == 0 || present == 0 || c.key > prev_key) { /* ok */ }
                if (present > 0 && c.key <= prev_key) return false;
                prev_key = c.key;
                present++;
                refs.push_back(c);
            }
            if (type == 2 && present < 3) return false;
            if (!rd.zero(rd.pos, 1)) return false;
        } else { // TYPE3
            pn.bulk_bitmap = rd.r(64);
            pn.bulk_base = static_cast<uint32_t>(rd.r(22));
            pn.bulk_stage = static_cast<int>(rd.r(4));
            int present = 0;
            uint32_t prev_key = 0;
            bool absent_seen = false;
            for (int i = 0; i < 3; ++i) {
                const uint64_t v = rd.r(32);
                if (v == CHILD_ABSENT) { absent_seen = true; continue; }
                if (absent_seen) return false;
                ChildRef c;
                if (!read_child(v, stage, origin, c.bulk, c)) return false;
                if (present > 0 && c.key <= prev_key) return false;
                if (pn.bulk_bitmap & (1ULL << c.key)) return false; // disjoint keys
                prev_key = c.key;
                present++;
                refs.push_back(c);
            }
            if (!rd.zero(rd.pos, 7)) return false;
            const int bcnt = popcnt64(pn.bulk_bitmap);
            if (bcnt < 4) return false;                 // bulk groups have >= 4 roots
            if (present > 3) return false;
            if (present + bcnt < 7) return false;       // TYPE3 has 7..64 children
            if (present + bcnt > 64) return false;
            if (pn.bulk_stage < 0 || pn.bulk_stage >= RAM_NUM) return false;
            if (pn.bulk_stage >= stage) return false;   // strictly lower stage
            if (pn.bulk_base & 1u) return false;        // bulk base is even
            if (static_cast<uint64_t>(pn.bulk_base) + 2ULL * static_cast<uint64_t>(bcnt) >
                d_->cells[static_cast<size_t>(pn.bulk_stage)])
                return false;
            for (int k = 0; k < 64; ++k) {
                if ((pn.bulk_bitmap >> k) & 1ULL) {
                    ChildRef c;
                    c.key = static_cast<uint8_t>(k);
                    c.stage = pn.bulk_stage;
                    c.bulk = true;
                    c.cell = pn.bulk_base +
                             2u * static_cast<uint32_t>(popcnt64(pn.bulk_bitmap & low_mask(k)));
                    refs.push_back(c);
                }
            }
        }

        // local prefixes derived from the NI bitmap, in increasing position
        uint32_t rank = 0;
        for (uint32_t pos = 1; pos < 64; ++pos) {
            if ((bm >> pos) & 1ULL) {
                const int l = bit_length(pos) - 1;
                const uint32_t v = pos - (1u << l);
                if (depth + l > max_len) return false;
                PrefixRec p;
                p.addr = region;
                or_bits(p.addr, depth, v, l);
                p.len = static_cast<uint8_t>(depth + l);
                p.hop = d_->nexthops[pn.ni_base + rank];
                pn.pfx.push_back(p);
                ++rank;
            }
        }
    }

    const size_t self = nodes_.size();
    nodes_.push_back(pn);
    index_[std::make_pair(stage, cell)] = self;

    uint64_t subtree = nodes_[self].pfx.size();
    for (size_t i = 0; i < refs.size(); ++i) {
        ip6_t cr = region;
        or_bits(cr, depth, refs[i].key, 6);
        const int cidx = static_cast<int>(nodes_.size());
        if (!parse(refs[i].stage, refs[i].cell, refs[i].bulk, origin, level + 1, cr))
            return false;
        refs[i].index = cidx;
        subtree += nodes_[static_cast<size_t>(cidx)].subtree;
    }
    nodes_[self].children = refs;
    nodes_[self].subtree = subtree;

    if (type == 4 && subtree != 1) return false;
    if (type == 5 && subtree != 2) return false;
    if ((type == 1 || type == 2 || type == 3) && subtree < 3) return false;

    for (size_t i = 0; i < nodes_[self].pfx.size(); ++i)
        fib_.push_back(nodes_[self].pfx[i]);
    return true;
}

bool Validator::read_child(uint64_t v, int stage, int origin, bool& bulk_out, ChildRef& out) {
    (void)origin;
    (void)bulk_out;
    const uint32_t key = static_cast<uint32_t>(v & 0x3Fu);
    const int st = static_cast<int>((v >> 6) & 0xFu);
    const uint32_t cell = static_cast<uint32_t>(v >> 10);
    if (st >= RAM_NUM) return false;                   // stage 15 only for absent
    if (st >= stage) return false;                     // strictly lower stage
    if (cell >= d_->cells[static_cast<size_t>(st)]) return false;
    out.key = static_cast<uint8_t>(key);
    out.stage = st;
    out.cell = cell;
    out.bulk = false;
    return true;
}

bool Validator::finish() {
    // every charged cell is covered exactly once
    for (int s = 0; s < RAM_NUM; ++s) {
        const uint32_t n = d_->cells[static_cast<size_t>(s)];
        for (uint32_t c = 0; c < n; ++c)
            if (!covered_[static_cast<size_t>(s)][c]) return false;
        if (n & 1u) {
            const std::bitset<256>& bits = d_->banks[static_cast<size_t>(s)].back();
            for (int i = 128; i < 256; ++i)
                if (bits[static_cast<size_t>(i)]) return false;
        }
    }

    // complete FIB: distinct normalized prefixes within the documented bound
    std::vector<PrefixRec> fib = fib_;
    std::sort(fib.begin(), fib.end());
    for (size_t i = 1; i < fib.size(); ++i)
        if (fib[i].addr == fib[i - 1].addr && fib[i].len == fib[i - 1].len) return false;
    if (fib.size() > static_cast<size_t>(MAX_FIB_ENTRIES)) return false;

    // NI arrays tile the NI vector without holes; all entries used
    std::vector<std::pair<uint32_t, uint32_t> > ranges;
    for (size_t i = 0; i < nodes_.size(); ++i) {
        const PNode& n = nodes_[i];
        if (n.type == 4 || n.type == 5) continue;
        if (n.ni_count > 0) ranges.push_back(std::make_pair(n.ni_base, n.ni_count));
    }
    std::sort(ranges.begin(), ranges.end());
    uint64_t expect = 0;
    for (size_t i = 0; i < ranges.size(); ++i) {
        if (ranges[i].first != expect) return false;
        expect += ranges[i].second;
    }
    if (expect != d_->nexthops.size()) return false;

    // every dictionary pattern is used
    std::vector<uint8_t> used(d_->bitmaps.size(), 0);
    for (size_t i = 0; i < nodes_.size(); ++i) {
        const PNode& n = nodes_[i];
        if (n.type == 4 || n.type == 5) continue;
        if (n.bitmap_id < used.size()) used[n.bitmap_id] = 1;
    }
    for (size_t i = 0; i < used.size(); ++i)
        if (!used[i]) return false;

    // the packed graph must be exactly the canonical structure of its own FIB
    Graph g = build_graph(fib);
    if ((g.root0 != nullptr) != (d_->root.stage >= 0)) return false;
    if (g.root0 != nullptr) {
        std::map<std::pair<int, uint32_t>, size_t>::const_iterator it =
            index_.find(std::make_pair(d_->root.stage, d_->root.cell));
        if (it == index_.end()) return false;
        if (!match(g.root0, it->second)) return false;
    }
    if (g.front16.size() != d_->front16.size()) return false;
    for (size_t i = 0; i < g.front16.size(); ++i) {
        if (g.front16[i].first != d_->front16[i].key) return false;
        std::map<std::pair<int, uint32_t>, size_t>::const_iterator it =
            index_.find(std::make_pair(d_->front16[i].loc.stage, d_->front16[i].loc.cell));
        if (it == index_.end()) return false;
        if (!match(g.front16[i].second, it->second)) return false;
    }
    if (g.front64.size() != d_->front64.size()) return false;
    for (size_t i = 0; i < g.front64.size(); ++i) {
        if (g.front64[i].first != d_->front64[i].key) return false;
        std::map<std::pair<int, uint32_t>, size_t>::const_iterator it =
            index_.find(std::make_pair(d_->front64[i].loc.stage, d_->front64[i].loc.cell));
        if (it == index_.end()) return false;
        if (!match(g.front64[i].second, it->second)) return false;
    }
    return true;
}

bool Validator::match(const GNode* gn, size_t idx) {
    const PNode& pn = nodes_[idx];
    if (gn->type != pn.type) return false;
    if (gn->bmp != pn.bmp) return false;
    if (gn->children.size() != pn.children.size()) return false;

    std::vector<PrefixRec> a = gn->pfx;
    std::vector<PrefixRec> b = pn.pfx;
    std::sort(a.begin(), a.end());
    std::sort(b.begin(), b.end());
    if (a.size() != b.size()) return false;
    for (size_t i = 0; i < a.size(); ++i)
        if (!(a[i] == b[i])) return false;

    for (size_t i = 0; i < gn->children.size(); ++i) {
        if (gn->keys[i] != pn.children[i].key) return false;
        if (pn.children[i].index < 0) return false;
        if (!match(gn->children[i], static_cast<size_t>(pn.children[i].index)))
            return false;
    }
    return true;
}

} // namespace

// ---------------------------------------------------------------------------
// loaded image state
// ---------------------------------------------------------------------------

bool MemoryImage::load(const ImageData& proposed) {
    Validator v;
    if (!v.run(proposed)) return false;
    data_ = proposed;
    valid_ = true;
    return true;
}

namespace {

// Longest prefix match inside one forest, decoding records from the banks.
nexthop_t forest_lookup(const ImageData& d, const ImageLoc& loc, const ip6_t& ip, int origin) {
    const int max_len = (origin == 0) ? 16 : (origin == 16 ? 64 : 128);
    int depth = origin;
    ImageLoc cur = loc;
    for (;;) {
        const std::bitset<256>& bits = d.banks[static_cast<size_t>(cur.stage)][cur.cell / 2];
        const int off = 128 * static_cast<int>(cur.cell & 1u);
        BitReader rd{bits, off};
        const uint32_t type = static_cast<uint32_t>(rd.r(3));
        const uint32_t bmp = static_cast<uint32_t>(rd.r(22));
        const uint32_t bmp_hop = (bmp == HOP_NULL) ? 0u : bmp;

        if (type == 4 || type == 5) {
            const int cnt = (type == 4) ? 1 : 2;
            uint32_t best = HOP_NULL;
            int best_len = -1;
            for (int i = 0; i < cnt; ++i) {
                const uint64_t frag = rd.r(64);
                const int rel = static_cast<int>(rd.r(8));
                const uint32_t hop = static_cast<uint32_t>(rd.r(22));
                const int glen = origin + rel;
                if (hop == HOP_NULL || glen <= best_len) continue;
                bool m = false;
                if (origin == 0) m = (frag == keep_top(ip.hi, rel));
                else if (origin == 16)
                    m = (rel >= 1 && rel <= 48 && frag == (get_bits(ip, 16, rel) << (64 - rel)));
                else m = (rel >= 1 && rel <= 64 && frag == keep_top(ip.lo, rel));
                if (m) { best = hop; best_len = glen; }
            }
            if (best != HOP_NULL) return best;
            return (bmp == HOP_NULL) ? LPM_INVALID_NH : static_cast<nexthop_t>(bmp_hop);
        }

        const uint32_t bitmap_id = static_cast<uint32_t>(rd.r(16));
        const uint32_t ni_base = static_cast<uint32_t>(rd.r(22));
        const uint64_t bm = (bitmap_id < d.bitmaps.size()) ? d.bitmaps[bitmap_id] : 0ULL;

        ImageLoc next;
        bool found = false;
        if (depth + 6 <= max_len) {
            const uint8_t v = static_cast<uint8_t>(get_bits(ip, depth, 6));
            if (type == 1 || type == 2) {
                const int slots = (type == 1) ? 2 : 6;
                for (int i = 0; i < slots && !found; ++i) {
                    const uint64_t rec = rd.r(32);
                    if (rec == CHILD_ABSENT) break;
                    if (static_cast<uint32_t>(rec & 0x3Fu) == v) {
                        next.stage = static_cast<int>((rec >> 6) & 0xFu);
                        next.cell = static_cast<uint32_t>(rec >> 10);
                        found = true;
                    }
                }
            } else {
                const uint64_t bulk_bitmap = rd.r(64);
                const uint32_t bulk_base = static_cast<uint32_t>(rd.r(22));
                const uint32_t bulk_stage = static_cast<uint32_t>(rd.r(4));
                for (int i = 0; i < 3 && !found; ++i) {
                    const uint64_t rec = rd.r(32);
                    if (rec == CHILD_ABSENT) break;
                    if (static_cast<uint32_t>(rec & 0x3Fu) == v) {
                        next.stage = static_cast<int>((rec >> 6) & 0xFu);
                        next.cell = static_cast<uint32_t>(rec >> 10);
                        found = true;
                    }
                }
                if (!found && ((bulk_bitmap >> v) & 1ULL)) {
                    const uint64_t rank = popcnt64(bulk_bitmap & low_mask(v));
                    next.stage = static_cast<int>(bulk_stage);
                    next.cell = bulk_base + 2u * static_cast<uint32_t>(rank);
                    found = true;
                }
            }
        }
        if (found) {
            cur = next;
            depth += 6;
            continue;
        }

        int lmax = 5;
        if (max_len - depth < lmax) lmax = max_len - depth;
        for (int l = lmax; l >= 0; --l) {
            const uint32_t pos = (1u << l) + static_cast<uint32_t>(get_bits(ip, depth, l));
            if ((bm >> pos) & 1ULL) {
                const uint64_t rank = popcnt64(bm & low_mask(pos));
                return static_cast<nexthop_t>(d.nexthops[ni_base + rank]);
            }
        }
        return (bmp == HOP_NULL) ? LPM_INVALID_NH : static_cast<nexthop_t>(bmp_hop);
    }
}

} // namespace

nexthop_t MemoryImage::lookup(ip6_t ip) const {
    if (data_.root.stage < 0 && data_.front16.empty() && data_.front64.empty())
        return LPM_INVALID_NH;

    if (!data_.front64.empty()) {
        size_t lo = 0, hi = data_.front64.size();
        while (lo < hi) {
            size_t mid = (lo + hi) / 2;
            if (data_.front64[mid].key < ip.hi) lo = mid + 1;
            else hi = mid;
        }
        if (lo < data_.front64.size() && data_.front64[lo].key == ip.hi) {
            nexthop_t r = forest_lookup(data_, data_.front64[lo].loc, ip, 64);
            if (r != LPM_INVALID_NH) return r;
        }
    }
    if (!data_.front16.empty()) {
        const uint64_t key = ip.hi >> 48;
        size_t lo = 0, hi = data_.front16.size();
        while (lo < hi) {
            size_t mid = (lo + hi) / 2;
            if (data_.front16[mid].key < key) lo = mid + 1;
            else hi = mid;
        }
        if (lo < data_.front16.size() && data_.front16[lo].key == key) {
            nexthop_t r = forest_lookup(data_, data_.front16[lo].loc, ip, 16);
            if (r != LPM_INVALID_NH) return r;
        }
    }
    if (data_.root.stage >= 0) {
        nexthop_t r = forest_lookup(data_, data_.root, ip, 0);
        if (r != LPM_INVALID_NH) return r;
    }
    return LPM_INVALID_NH;
}
